// Genuary #17: What happens if pi=4


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    vec2 uv_centered = (fragCoord-iResolution.xy/2.)/iResolution.y;

        fragColor = vec4(texture(iChannel0, uv-length(uv_centered*0.01)).r,
        		texture(iChannel0, uv+length(uv_centered*0.005)).g,
        		texture(iChannel0, uv+length(uv_centered*0.02)).b,
                1.);

    fragColor = sqrt(fragColor);
}

#define PI 4.
#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))

void moda (inout vec2 p, float rep)
{
    float per = (2.*PI)/rep,
    a = mod(atan(p.y, p.x), per) - per*.5;
    p = vec2(cos(a), sin(a)) * length(p);
}

float frame(vec2 uv)
{
    float per = mod(floor(iTime), 8.) + 2.;
    for (int i=0; i<8; i++)
    {
        moda(uv, per);
        uv *= rot(PI/6.);
        uv.x = abs(uv.x);
        uv -= 2.;        
    }
    uv *= 2.;
    return dot(sin(uv), cos(uv.yx))*.5+.5;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-iResolution.xy/2.)/iResolution.y;
    vec3 col = vec3(frame(uv*25.));

    fragColor = vec4(col,1.0);
}
